use std::io::{self, Write};

/// Each octet owns its color. Zero is the sole palette exception.
fn tint(text: &str, byte: u8, enabled: bool) -> String {
    if enabled {
        let color = if byte == 0 { 22 } else { byte };
        format!("\x1b[38;5;{color}m{text}\x1b[0m")
    } else {
        text.to_owned()
    }
}

fn octet(byte: u8, format: &str, prefix: bool) -> String {
    let (tag, digits) = match format {
        "o" => ("0o", format!("{byte:04o}")),
        "b" => ("0b", format!("{byte:08b}")),
        "X" => ("0x", format!("{byte:02X}")),
        _ => ("0x", format!("{byte:02x}")),
    };
    if prefix { format!("{tag}{digits}") } else { digits }
}

pub fn dump<W: Write>(
    out: &mut W,
    data: &[u8],
    columns: usize,
    format: &str,
    prefix: bool,
    color: bool,
) -> io::Result<()> {
    let step = columns.max(1);
    let mut start = 0;
    loop {
        write!(out, "0x{start:06x}: ")?;
        let end = start.saturating_add(step).min(data.len());
        let row = &data[start..end];
        for &byte in row {
            write!(out, "{} ", tint(&octet(byte, format, prefix), byte, color))?;
        }
        // Padding counts absent octets, not the chosen base's printed width.
        for _ in row.len()..columns {
            write!(out, "     ")?;
        }
        for &byte in row {
            let ch = if (32..=126).contains(&byte) { byte as char } else { '.' };
            write!(out, "{}", tint(&ch.to_string(), byte, color))?;
        }
        writeln!(out)?;
        if row.len() < step {
            break;
        }
        start = end;
    }
    writeln!(out, "   bytes: {}", data.len())
}

pub fn array<W: Write>(out: &mut W, data: &[u8], columns: usize, language: &str) -> io::Result<()> {
    let len = data.len();
    let (head, tail) = match language {
        "r" => (format!("let ARRAY: [u8; {len}] = ["), "];") ,
        "c" => (format!("unsigned char ARRAY[{len}] = {{"), "};"),
        "g" => (format!("a := [{len}]byte{{"), "}"),
        "p" => ("a = [".to_owned(), "]"),
        "k" => ("val a = byteArrayOf(".to_owned(), ")"),
        "j" => ("byte[] a = new byte[]{".to_owned(), "};"),
        "s" => ("let a: [UInt8] = [".to_owned(), "]"),
        _ => ("let a = [|".to_owned(), "|]"),
    };
    writeln!(out, "{head}")?;
    write!(out, "    ")?;
    let mut count = 0;
    for (index, &byte) in data.iter().enumerate() {
        write!(out, "0x{byte:02x}")?;
        if language == "f" {
            write!(out, "uy")?;
        }
        if index + 1 < len || language == "g" {
            write!(out, "{} ", if language == "f" { ";" } else { "," })?;
        }
        count += 1;
        if count >= columns {
            write!(out, "\n    ")?;
            count = 0;
        }
    }
    writeln!(out, "\n{tail}")
}

pub fn wave<W: Write>(out: &mut W, length: usize, places: usize) -> io::Result<()> {
    for i in 0..length {
        let angle = (i as f64 / length as f64) * std::f64::consts::FRAC_PI_2;
        write!(out, "{:.*},", places, angle.sin())?;
        if (i + 1) % 10 == 0 {
            writeln!(out)?;
        }
    }
    writeln!(out)
}
EOF"}

