{"command":"cat > src/cli.rs <<'EOF'
use std::env;
use std::ffi::OsString;
use std::io::{self, IsTerminal};
use std::path::Path;

pub const COLS: usize = 0;
pub const LEN: usize = 1;
pub const FORMAT: usize = 2;
pub const COLOR: usize = 3;
pub const ARRAY: usize = 4;
pub const FUNC: usize = 5;
pub const PLACES: usize = 6;
pub const PREFIX: usize = 7;

struct Spec {
    short: char,
    long: &'static str,
    value: &'static str,
    description: &'static str,
    choices: &'static [&'static str],
}

static SPECS: [Spec; 10] = [
    Spec { short: 'c', long: "cols", value: "columns", description: "Set column length", choices: &[] },
    Spec { short: 'l', long: "len", value: "len", description: "Set <len> bytes to read", choices: &[] },
    Spec { short: 'f', long: "format", value: "format", description: "Set format of octet: Octal (o), LowerHex (x), UpperHex (X), Binary (b)", choices: &["o", "x", "X", "b"] },
    Spec { short: 't', long: "color", value: "color", description: "Set color tint terminal output. 0..disable, 1 to enable", choices: &["0", "1"] },
    Spec { short: 'a', long: "array", value: "array_format", description: "Set source code format output: rust (r), C (c), golang (g), python (p), kotlin (k), java (j), swift (s), fsharp (f)", choices: &["r", "c", "g", "p", "k", "j", "s", "f"] },
    Spec { short: 'u', long: "func", value: "func_length", description: "Set function wave length", choices: &[] },
    Spec { short: 'p', long: "places", value: "func_places", description: "Set function wave output decimal places", choices: &[] },
    Spec { short: 'r', long: "prefix", value: "prefix", description: "Include prefix in output (e.g. 0x/0b/0o). 0 to disable, 1 to enable", choices: &["0", "1"] },
    Spec { short: 'h', long: "help", value: "", description: "Print help", choices: &[] },
    Spec { short: 'V', long: "version", value: "", description: "Print version", choices: &[] },
];

#[derive(Default)]
pub struct Options {
    pub values: [Option<String>; 8],
    pub input: Option<String>,
}

impl Options {
    pub fn value(&self, key: usize) -> Option<&str> {
        self.values[key].as_deref()
    }
}

pub struct Output {
    pub text: String,
    pub status: i32,
    pub stderr: bool,
}

#[derive(Clone, Copy)]
struct Style(bool);

impl Style {
    fn paint(&self, text: &str, code: &str) -> String {
        if self.0 { format!("{code}{text}\x1b[0m") } else { text.to_owned() }
    }
    fn bold(&self, text: &str) -> String { self.paint(text, "\x1b[1m") }
    fn heading(&self, text: &str) -> String { self.paint(text, "\x1b[1m\x1b[4m") }
    fn good(&self, text: &str) -> String { self.paint(text, "\x1b[32m") }
    fn bad(&self, text: &str) -> String { self.paint(text, "\x1b[33m") }
    fn error(&self) -> String { self.paint("error:", "\x1b[1m\x1p[31m".replace("\x1p", "\x1b").as_str()) }
}

fn nonempty_env(key: &str) -> Option<OsString> {
    env::var_os(key).filter(|value| !value.is_empty())
}

fn cli_color(terminal: bool) -> bool {
    if nonempty_env("NO_COLOR").is_some() { return false; }
    if let Some(value) = nonempty_env("CLICOLOR_FORCE") {
        if value != "0" { return true; }
    }
    if env::var_os("CLICOLOR").as_deref() == Some(std::ffi::OsStr::new("0")) { return false; }
    terminal && nonempty_env("TERM").is_some_and(|value| value != "dumb")
}

struct Parser {
    name: String,
    out_style: Style,
    err_style: Style,
    options: Options,
    used: Vec<usize>,
}

impl Parser {
    fn label(key: usize) -> String {
        let s = &SPECS[key];
        if s.value.is_empty() { format!("--{}", s.long) } else { format!("--{} <{}>", s.long, s.value) }
    }

    fn usage(&self, style: Style, subset: Option<&[usize]>, input: bool) -> String {
        let mut line = format!("{} {}", style.heading("Usage:"), style.bold(&self.name));
        if let Some(keys) = subset {
            if keys.is_empty() && !input {
                line.push_str(" [OPTIONS]");
            }
            for &key in keys {
                let spec = &SPECS[key];
                line.push(' ');
                line.push_str(&style.bold(&format!("--{}", spec.long)));
                if !spec.value.is_empty() {
                    line.push_str(&format!(" <{}>", spec.value));
                }
            }
        } else {
            line.push_str(" [OPTIONS]");
        }
        line.push_str(if input { " <INPUTFILE>" } else { " [INPUTFILE]" });
        line
    }

    fn more(&self) -> String {
        format!("For more information, try '{}'.\n", self.err_style.bold("--help"))
    }

    fn error(&self, body: String) -> Output {
        Output { text: format!("{} {body}", self.err_style.error()), status: 2, stderr: true }
    }

    fn missing(&self, key: usize) -> Output {
        let mut body = format!("a value is required for '{}' but none was supplied\n", self.err_style.bad(&Self::label(key)));
        body.push_str(&self.possibilities(key));
        body.push('\n');
        body.push_str(&self.more());
        self.error(body)
    }

    fn possibilities(&self, key: usize) -> String {
        let choices = SPECS[key].choices;
        if choices.is_empty() { return String::new(); }
        let items: Vec<_> = choices.iter().map(|s| self.err_style.good(s)).collect();
        format!("  [possible values: {}]\n", items.join(", "))
    }

    fn invalid_value(&self, key: usize, value: &str) -> Output {
        if value.is_empty() { return self.missing(key); }
        let mut body = format!("invalid value '{}' for '{}'\n", self.err_style.bad(value), self.err_style.bold(&Self::label(key)));
        body.push_str(&self.possibilities(key));
        body.push('\n');
        if let Some(index) = closest(value, SPECS[key].choices.iter().copied()) {
            body.push_str(&format!("  {} a similar value exists: '{}'\n\n", self.err_style.good("tip:"), self.err_style.good(SPECS[key].choices[index])));
        }
        body.push_str(&self.more());
        self.error(body)
    }

    fn duplicate(&self, key: usize) -> Output {
        self.error(format!("the argument '{}' cannot be used multiple times\n\n{}\n\n{}",
            self.err_style.bad(&Self::label(key)), self.usage(self.err_style, None, false), self.more()))
    }

    fn invalid_utf8(&self) -> Output {
        self.error(format!("invalid UTF-8 was detected in one or more arguments\n\n{}\n\n{}",
            self.usage(self.err_style, None, false), self.more()))
    }

    fn unexpected(&self, token: &str, long: bool, flag: bool) -> Output {
        let mut body = format!("unexpected argument '{}' found\n\n", self.err_style.bad(token));
        let mut keys = self.used.clone();
        if long {
            if let Some(key) = closest(token.trim_start_matches("--"), SPECS.iter().map(|spec| spec.long)) {
                body.push_str(&format!("  {} a similar argument exists: '{}'\n\n", self.err_style.good("tip:"), self.err_style.good(&format!("--{}", SPECS[key].long))));
                if !keys.contains(&key) { keys.push(key); }
            } else {
                body.push_str(&format!("  {} to pass '{}' as a value, use '{}'\n\n", self.err_style.good("tip:"), self.err_style.bad(token), self.err_style.good(&format!("-- {token}"))));
            }
        } else if flag {
            body.push_str(&format!("  {} to pass '{}' as a value, use '{}'\n\n", self.err_style.good("tip:"), self.err_style.bad(token), self.err_style.good(&format!("-- {token}"))));
        }
        body.push_str(&self.usage(self.err_style, if long { Some(&keys) } else { None }, long && self.options.input.is_some()));
        body.push_str("\n\n");
        body.push_str(&self.more());
        self.error(body)
    }

    fn excess_flag_value(&self, key: usize, value: &str) -> Output {
        self.error(format!("unexpected value '{}' for '{}' found; no more were expected\n\n{}\n\n{}",
            self.err_style.bad(value), self.err_style.bold(&Self::label(key)),
            self.usage(self.err_style, Some(&[key]), false), self.more()))
    }

    fn help(&self) -> Output {
        let s = self.out_style;
        let mut text = format!("Futuristic take on hexdump, made in Rust.\n\n\n{}\n\n{}\n  [INPUTFILE]  Pass file path as an argument, or input data may be passed via stdin\n\n{}\n",
            self.usage(s, None, false), s.heading("Arguments:"), s.heading("Options:"));
        for spec in &SPECS {
            let mut plain = format!("-{}, --{}", spec.short, spec.long);
            let mut styled = format!("{}, {}", s.bold(&format!("-{}", spec.short)), s.bold(&format!("--{}", spec.long)));
            if !spec.value.is_empty() {
                let suffix = format!(" <{}>", spec.value);
                plain.push_str(&suffix);
                styled.push_str(&suffix);
            }
            text.push_str("  ");
            text.push_str(&styled);
            text.push_str(&" ".repeat(28usize.saturating_sub(plain.len())));
            text.push_str(&spec.description.replace("0..disable", "0 to disable"));
            if !spec.choices.is_empty() {
                text.push_str(&format!(" [possible values: {}]", spec.choices.join(", ")));
            }
            text.push('\n');
        }
        Output { text, status: 0, stderr: false }
    }

    fn parse(mut self, args: &[OsString]) -> Result<Options, Output> {
        let mut index = 0;
        let mut literal = false;
        while index < args.len() {
            let token = args[index].to_str().ok_or_else(|| self.invalid_utf8())?;
            index += 1;
            if !literal && token == "--" {
                literal = true;
                continue;
            }
            if literal || token == "-" || !token.starts_with('-') {
                if self.options.input.is_some() { return Err(self.unexpected(token, false, false)); }
                self.options.input = Some(token.to_owned());
                continue;
            }
            let (key, inline, long) = if let Some(rest) = token.strip_prefix("--") {
                let (name, inline) = match rest.split_once('=') {
                    Some((name, value)) => (name, Some(value)),
                    None => (rest, None),
                };
                let key = SPECS.iter().position(|spec| spec.long == name)
                    .ok_or_else(|| self.unexpected(&format!("--{name}"), true, true))?;
                (key, inline, true)
            } else {
                let rest = &token[1..];
                let short = rest.chars().next().unwrap();
                let key = SPECS.iter().position(|spec| spec.short == short)
                    .ok_or_else(|| self.unexpected(&format!("-{short}"), false, true))?;
                let remaining = &rest[short.len_utf8()..];
                let inline = if remaining.is_empty() { None } else { Some(remaining.strip_prefix('=').unwrap_or(remaining)) };
                (key, inline, false)
            };
            if key >= 8 {
                if long {
                    if let Some(value) = inline { return Err(self.excess_flag_value(key, value)); }
                }
                return Err(if key == 8 { self.help() } else { Output { text: "hx 0.7.0\n".to_owned(), status: 0, stderr: false } });
            }
            let value = if let Some(value) = inline {
                value
            } else {
                if index == args.len() { return Err(self.missing(key)); }
                let next = args[index].to_str().ok_or_else(|| self.invalid_utf8())?;
                if next.starts_with('-') && next != "-" {
                    if next == "--" { return Err(self.missing(key)); }
                    if let Some(rest) = next.strip_prefix("--") {
                        let name = rest.split('=').next().unwrap_or(rest);
                        if !SPECS.iter().any(|spec| spec.long == name) {
                            return Err(self.unexpected(&format!("--{name}"), true, true));
                        }
                    } else {
                        let ch = next[1..].chars().next().unwrap();
                        if !SPECS.iter().any(|spec| spec.short == ch) {
                            return Err(self.unexpected(&format!("-{ch}"), false, true));
                        }
                    }
                    return Err(self.missing(key));
                }
                index += 1;
                next
            };
            if self.options.values[key].is_some() { return Err(self.duplicate(key)); }
            let choices = SPECS[key].choices;
            if !choices.is_empty() && !choices.contains(&value) { return Err(self.invalid_value(key, value)); }
            self.options.values[key] = Some(value.to_owned());
            self.used.push(key);
        }
        Ok(self.options)
    }
}

// Similarity is used only to offer a spelling hint, never to accept an option.
fn similarity(a: &str, b: &str) -> f64 {
    let a: Vec<_> = a.chars().collect();
    let b: Vec<_> = b.chars().collect();
    if a == b { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    let radius = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut am = vec![false; a.len()];
    let mut bm = vec![false; b.len()];
    let mut matches = 0;
    for i in 0..a.len() {
        for j in i.saturating_sub(radius)..(i + radius + 1).min(b.len()) {
            if !bm[j] && a[i] == b[j] {
                am[i] = true;
                bm[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mismatches = a.iter().zip(&am).filter(|(_, flag)| **flag).map(|(c, _)| c)
        .zip(b.iter().zip(&bm).filter(|(_, flag)| **flag).map(|(c, _)| c))
        .filter(|(a, b)| a != b).count();
    let m = matches as f64;
    let mut score = (m / a.len() as f64 + m / b.len() as f64 + (m - mismatches as f64 / 2.0) / m) / 3.0;
    if score > 0.7 {
        let common = a.iter().zip(&b).take(4).take_while(|(a, b)| a == b).count();
        score += common as f64 * 0.1 * (1.0 - score);
    }
    score
}

fn closest<'a>(value: &str, candidates: impl Iterator<Item = &'a str>) -> Option<usize> {
    let mut best = None;
    let mut score = 0.7;
    for (index, candidate) in candidates.enumerate() {
        let current = similarity(value, candidate);
        if current > score {
            best = Some(index);
            score = current;
        }
    }
    best
}

pub fn parse() -> Result<Options, Output> {
    let mut args = env::args_os();
    let arg0 = args.next().unwrap_or_else(|| OsString::from("hx"));
    let name = Path::new(&arg0).file_name().unwrap_or(arg0.as_os_str()).to_string_lossy().into_owned();
    let parser = Parser {
        name,
        out_style: Style(cli_color(io::stdout().is_terminal())),
        err_style: Style(cli_color(io::stderr().is_terminal())),
        options: Options::default(),
        used: Vec::new(),
    };
    parser.parse(&args.collect::<Vec<_>>())
}
