mod cli;
mod render;

use std::env;
use std::fs::File;
use std::io::{self, IsTerminal, Read, Write};
use std::process;

fn number(options: &cli::Options, key: usize, default: usize, short: char, long: &str) -> Result<usize, String> {
    let Some(value) = options.value(key) else { return Ok(default); };
    value.parse::<usize>().map_err(|error| {
        eprintln!("-{short}, --{long} <integer> expected. {error:?}");
        error.to_string()
    })
}

fn run(options: cli::Options) -> Result<(), String> {
    let stdout = io::stdout();
    if options.value(cli::FUNC).is_some() {
        let places = number(&options, cli::PLACES, 4, 'p', "places")?;
        let length = number(&options, cli::FUNC, 0, "u".chars().next().unwrap(), "func")?;
        let mut out = stdout.lock();
        render::wave(&mut out, length, places).map_err(|error| error.to_string())?;
        return out.flush().map_err(|error| error.to_string());
    }

    // Open the source before parsing dump-specific settings; actual reads follow
    // the settings. This also permits pipes and other non-seekable inputs.
    let mut input: Box<dyn Read> = if let Some(path) = options.input.as_deref() {
        Box::new(File::open(path).map_err(|error| error.to_string())?)
    } else {
        Box::new(io::stdin())
    };
    let columns = number(&options, cli::COLS, 10, 'c', "cols")?;
    let length = number(&options, cli::LEN, 0, 'l', "len")?;
    let mut data = Vec::new();
    if length == 0 {
        input.read_to_end(&mut data).map_err(|error| error.to_string())?;
    } else {
        input.take(length as u64).read_to_end(&mut data).map_err(|error| error.to_string())?;
    }

    let color = match options.value(cli::COLOR) {
        Some("1") => true,
        Some("0") => false,
        _ => stdout.is_terminal() && env::var_os("NO_COLOR").is_none(),
    };
    let mut out = stdout.lock();
    if let Some(language) = options.value(cli::ARRAY) {
        render::array(&mut out, &data, columns, language)
    } else {
        render::dump(&mut out, &data, columns, options.value(cli::FORMAT).unwrap_or("x"), options.value(cli::PREFIX) != Some("0"), color)
    }.map_err(|error| error.to_string())?;
    out.flush().map_err(|error| error.to_string())
}

fn main() {
    let options = match cli::parse() {
        Ok(options) => options,
        Err(output) => {
            if output.stderr { eprint!("{}", output.text); } else { print!("{}", output.text); }
            process::exit(output.status);
        }
    };
    if let Err(error) = run(options) {
        eprintln!("error: {error}");
        process::exit(1);
    }
}
